'use client'

import { useId, useState } from 'react'
import type { KeyboardEvent, ReactNode } from 'react'
import { cn } from '@/lib/utils'

export type RetroAccordionItem = {
  id: string
  title: string
  content: ReactNode
  disabled?: boolean
}

type RetroAccordionProps = {
  items: RetroAccordionItem[]
  type?: 'single' | 'multiple'
  defaultValue?: string[]
  className?: string
}

export function RetroAccordion({ items, type = 'single', defaultValue = [], className }: RetroAccordionProps) {
  const [open, setOpen] = useState<string[]>(defaultValue)
  const baseId = useId()

  function toggle(id: string) {
    setOpen((current) => {
      if (current.includes(id)) return current.filter((value) => value !== id)
      return type === 'single' ? [id] : [...current, id]
    })
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const triggers = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('[data-accordion-trigger]:not(:disabled)')]
    const index = triggers.findIndex((trigger) => trigger === document.activeElement)
    if (index < 0) return
    const target =
      event.key === 'ArrowDown'
        ? triggers[(index + 1) % triggers.length]
        : event.key === 'ArrowUp'
          ? triggers[(index - 1 + triggers.length) % triggers.length]
          : event.key === 'Home'
            ? triggers[0]
            : event.key === 'End'
              ? triggers[triggers.length - 1]
              : undefined
    if (target) {
      event.preventDefault()
      target.focus()
    }
  }

  return (
    <div onKeyDown={onKeyDown} className={cn('flex flex-col gap-1', className)}>
      {items.map((item) => {
        const isOpen = open.includes(item.id)
        const triggerId = `${baseId}-trigger-${item.id}`
        const panelId = `${baseId}-panel-${item.id}`
        return (
          <div key={item.id}>
            <button
              id={triggerId}
              type="button"
              data-accordion-trigger=""
              aria-expanded={isOpen}
              aria-controls={panelId}
              disabled={item.disabled}
              onClick={() => toggle(item.id)}
              className={cn(
                'rt-raised flex w-full items-center gap-2 px-2 py-1 text-left text-[13px] font-medium text-rt-ink select-none',
                'aria-expanded:rt-pressed focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rt-accent',
                'disabled:cursor-not-allowed disabled:text-rt-shadow',
              )}
            >
              <span aria-hidden="true" className="rt-sunken grid size-3.5 shrink-0 place-items-center bg-rt-paper font-rt-mono text-[11px] leading-none">
                {isOpen ? '-' : '+'}
              </span>
              {item.title}
            </button>
            <div
              id={panelId}
              role="region"
              aria-labelledby={triggerId}
              hidden={!isOpen}
              className="rt-sunken mt-0.5 bg-rt-paper p-2.5 text-[13px] leading-snug text-rt-ink"
            >
              {item.content}
            </div>
          </div>
        )
      })}
    </div>
  )
}

import { cn } from '@/lib/utils'

export type RetroBreadcrumbItem = {
  label: string
  href?: string
}

type RetroBreadcrumbProps = {
  items: RetroBreadcrumbItem[]
  label?: string
  className?: string
}

export function RetroBreadcrumb({ items, label = 'Breadcrumb', className }: RetroBreadcrumbProps) {
  return (
    <nav aria-label={label} className={className}>
      <ol className="flex flex-wrap items-center gap-1 text-[13px] text-rt-ink">
        {items.map((item, index) => {
          const isLast = index === items.length - 1
          return (
            <li key={`${item.label}-${index}`} className="flex items-center gap-1">
              {isLast || !item.href ? (
                <span aria-current={isLast ? 'page' : undefined} className={cn(isLast && 'font-semibold')}>
                  {item.label}
                </span>
              ) : (
                <a
                  href={item.href}
                  className="underline underline-offset-2 hover:text-rt-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rt-accent"
                >
                  {item.label}
                </a>
              )}
              {isLast ? null : (
                <span aria-hidden="true" className="font-rt-mono text-rt-shadow">
                  {'\\'}
                </span>
              )}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

import type { AnchorHTMLAttributes, ButtonHTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

type Variant = 'default' | 'primary'
type Size = 'sm' | 'md'

const base = cn(
  'rt-raised inline-flex items-center justify-center gap-1.5 text-[13px] font-medium text-rt-ink select-none',
  'transition-[filter,box-shadow] duration-100 hover:brightness-105',
  'active:rt-pressed active:[&>span]:translate-y-px',
  'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rt-accent',
)

const sizes: Record<Size, string> = {
  md: 'min-h-7 px-4',
  sm: 'min-h-5.5 px-2 text-[12px]',
}

type RetroButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: Variant
  size?: Size
}

export function RetroButton({
  variant = 'default',
  size = 'md',
  className,
  children,
  type = 'button',
  ...props
}: RetroButtonProps) {
  return (
    <button
      type={type}
      className={cn(
        base,
        'disabled:cursor-not-allowed disabled:text-rt-shadow disabled:[text-shadow:1px_1px_0_var(--color-rt-light)] disabled:hover:brightness-100',
        sizes[size],
        variant === 'primary' && 'enabled:rt-primary enabled:active:rt-primary-pressed',
        className,
      )}
      {...props}
    >
      <span className="inline-flex items-center gap-1.5">{children}</span>
    </button>
  )
}

type RetroLinkButtonProps = AnchorHTMLAttributes<HTMLAnchorElement> & {
  variant?: Variant
  size?: Size
}

export function RetroLinkButton({
  variant = 'default',
  size = 'md',
  className,
  children,
  ...props
}: RetroLinkButtonProps) {
  return (
    <a
      className={cn(
        base,
        'no-underline',
        sizes[size],
        variant === 'primary' && 'any-link:rt-primary any-link:active:rt-primary-pressed',
        className,
      )}
      {...props}
    >
      <span className="inline-flex items-center gap-1.5">{children}</span>
    </a>
  )
}

'use client'

import { useEffect, useRef } from 'react'
import type { ReactNode } from 'react'
import { RetroWindow } from './retro-window'

type RetroDialogProps = {
  open: boolean
  onClose: () => void
  title: string
  children: ReactNode
  actions?: ReactNode
}

export function RetroDialog({ open, onClose, title, children, actions }: RetroDialogProps) {
  const ref = useRef<HTMLDialogElement>(null)

  useEffect(() => {
    const dialog = ref.current
    if (!dialog) return
    if (open && !dialog.open) dialog.showModal()
    if (!open && dialog.open) dialog.close()
  }, [open])

  return (
    <dialog
      ref={ref}
      onClose={onClose}
      aria-label={title}
      className="m-auto w-[min(92vw,26rem)] bg-transparent p-0 backdrop:bg-black/45 backdrop:backdrop-blur-[2px]"
    >
      <RetroWindow title={title} onClose={onClose}>
        <div className="flex gap-3 p-4">{children}</div>
        {actions ? <div className="flex justify-center gap-2 px-4 pb-4">{actions}</div> : null}
      </RetroWindow>
    </dialog>
  )
}

'use client'

import { useEffect, useId, useRef, useState } from 'react'
import type { KeyboardEvent } from 'react'
import { cn } from '@/lib/utils'

export type RetroMenuItem =
  | { separator: true }
  | { label: string; shortcut?: string; disabled?: boolean; onSelect?: () => void }

type RetroDropdownMenuProps = {
  label: string
  items: RetroMenuItem[]
  align?: 'start' | 'end'
  className?: string
}

const enabledIndices = (items: RetroMenuItem[]) =>
  items.flatMap((item, index) => ('separator' in item || item.disabled ? [] : [index]))

export function RetroDropdownMenu({ label, items, align = 'start', className }: RetroDropdownMenuProps) {
  const [open, setOpen] = useState(false)
  const rootRef = useRef<HTMLDivElement>(null)
  const triggerRef = useRef<HTMLButtonElement>(null)
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([])
  const initialFocus = useRef<'first' | 'last'>('first')
  const menuId = useId()

  useEffect(() => {
    if (!open) return
    const list = enabledIndices(items)
    const target = initialFocus.current === 'last' ? list[list.length - 1] : list[0]
    itemRefs.current[target]?.focus()
    const onPointerDown = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open, items])

  function close(refocus: boolean) {
    setOpen(false)
    if (refocus) triggerRef.current?.focus()
  }

  function openWith(position: 'first' | 'last') {
    initialFocus.current = position
    setOpen(true)
  }

  function onTriggerKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      openWith(event.key === 'ArrowDown' ? 'first' : 'last')
    }
  }

  function onMenuKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const list = enabledIndices(items)
    const position = list.indexOf(itemRefs.current.findIndex((el) => el === document.activeElement))
    const focusAt = (index: number | undefined) => {
      if (index !== undefined) itemRefs.current[index]?.focus()
    }
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        focusAt(list[(position + 1) % list.length])
        break
      case 'ArrowUp':
        event.preventDefault()
        focusAt(position <= 0 ? list[list.length - 1] : list[position - 1])
        break
      case 'Home':
        event.preventDefault()
        focusAt(list[0])
        break
      case 'End':
        event.preventDefault()
        focusAt(list[list.length - 1])
        break
      case 'Escape':
        event.preventDefault()
        close(true)
        break
      case 'Tab':
        close(false)
        break
    }
  }

  return (
    <div ref={rootRef} className={cn('relative inline-block', className)}>
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? menuId : undefined}
        onClick={() => (open ? close(false) : openWith('first'))}
        onKeyDown={onTriggerKeyDown}
        className={cn(
          'rt-raised inline-flex min-h-7 items-center gap-2 px-3 text-[13px] font-medium text-rt-ink select-none',
          'hover:brightness-105 active:rt-pressed aria-expanded:rt-pressed',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rt-accent',
        )}
      >
        {label}
        <svg aria-hidden="true" viewBox="0 0 8 8" className="size-2 fill-current">
          <path d="M0 2h8L4 7z" />
        </svg>
      </button>
      {open ? (
        <div
          id={menuId}
          role="menu"
          aria-label={label}
          onKeyDown={onMenuKeyDown}
          className={cn(
            'rt-raised absolute top-full z-20 mt-1 min-w-48 p-0.5 shadow-[0_8px_20px_-6px_rgb(0_0_0/0.5)]',
            align === 'end' ? 'right-0' : 'left-0',
          )}
        >
          {items.map((item, index) =>
            'separator' in item ? (
              <div
                key={`separator-${index}`}
                role="separator"
                className="mx-1 my-0.5 h-px bg-rt-shadow shadow-[0_1px_0_var(--color-rt-light)]"
              />
            ) : (
              <button
                key={item.label}
                ref={(element) => {
                  itemRefs.current[index] = element
                }}
                type="button"
                role="menuitem"
                tabIndex={-1}
                disabled={item.disabled}
                onMouseEnter={(event) => event.currentTarget.focus()}
                onClick={() => {
                  item.onSelect?.()
                  close(true)
                }}
                className={cn(
                  'flex w-full items-center justify-between gap-6 rounded-[2px] px-3 py-1 text-left text-[13px] text-rt-ink',
                  'focus-visible:bg-rt-accent focus-visible:text-rt-on-accent focus-visible:outline-none',
                  'disabled:cursor-not-allowed disabled:text-rt-shadow disabled:[text-shadow:1px_1px_0_var(--color-rt-light)]',
                )}
              >
                <span>{item.label}</span>
                {item.shortcut ? <span className="font-mono text-[11px] opacity-70">{item.shortcut}</span> : null}
              </button>
            ),
          )}
        </div>
      ) : null}
    </div>
  )
}

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

export function RetroProgress({
  value,
  label,
  className,
}: {
  value: number
  label: string
  className?: string
}) {
  const clamped = Math.min(100, Math.max(0, value))
  return (
    <div
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(clamped)}
      className={cn('rt-sunken h-5.5 p-0.5', className)}
    >
      <div
        className="h-full bg-[repeating-linear-gradient(90deg,var(--color-rt-accent)_0_9px,transparent_9px_12px)] transition-[width] duration-200"
        style={{ width: `${clamped}%` }}
      />
    </div>
  )
}

const tones = {
  neutral: 'bg-rt-face text-rt-ink',
  info: 'bg-rt-accent text-rt-on-accent',
  warn: 'bg-rt-warn text-rt-ink',
  ok: 'bg-rt-ok text-rt-on-accent',
  danger: 'bg-rt-danger text-rt-on-accent',
} as const

export function RetroBadge({
  tone = 'neutral',
  children,
  className,
}: {
  tone?: keyof typeof tones
  children: ReactNode
  className?: string
}) {
  return (
    <span
      className={cn(
        'inline-flex items-center rounded-[2px] border border-rt-line px-1.5 py-px font-rt-mono text-[11px] font-semibold tracking-wide uppercase shadow-[1px_1px_0_rgb(0_0_0/0.35)]',
        tones[tone],
        className,
      )}
    >
      {children}
    </span>
  )
}

import { useId } from 'react'
import type { InputHTMLAttributes, ReactNode, SelectHTMLAttributes, TextareaHTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

const focusRing =
  'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-rt-accent'

type RetroInputProps = InputHTMLAttributes<HTMLInputElement> & {
  label?: string
  hint?: string
}

export function RetroInput({ label, hint, className, id, ...props }: RetroInputProps) {
  const autoId = useId()
  const inputId = id ?? autoId
  return (
    <div className="flex flex-col gap-1">
      {label ? (
        <label htmlFor={inputId} className="font-medium">
          {label}
        </label>
      ) : null}
      <input
        id={inputId}
        aria-describedby={hint ? `${inputId}-hint` : undefined}
        className={cn(
          'rt-sunken h-7 px-2 text-[13px] text-rt-ink placeholder:text-rt-shadow',
          'disabled:cursor-not-allowed disabled:bg-rt-face disabled:text-rt-shadow',
          focusRing,
          className,
        )}
        {...props}
      />
      {hint ? (
        <p id={`${inputId}-hint`} className="text-[12px] text-rt-shadow">
          {hint}
        </p>
      ) : null}
    </div>
  )
}

type RetroTextareaProps = TextareaHTMLAttributes<HTMLTextAreaElement> & {
  label?: string
  hint?: string
}

export function RetroTextarea({ label, hint, className, id, rows = 4, ...props }: RetroTextareaProps) {
  const autoId = useId()
  const textareaId = id ?? autoId
  return (
    <div className="flex flex-col gap-1">
      {label ? (
        <label htmlFor={textareaId} className="font-medium">
          {label}
        </label>
      ) : null}
      <textarea
        id={textareaId}
        rows={rows}
        aria-describedby={hint ? `${textareaId}-hint` : undefined}
        className={cn(
          'rt-sunken rt-scroll min-h-16 resize-y p-2 text-[13px] leading-snug text-rt-ink placeholder:text-rt-shadow',
          'disabled:cursor-not-allowed disabled:bg-rt-face disabled:text-rt-shadow',
          focusRing,
          className,
        )}
        {...props}
      />
      {hint ? (
        <p id={`${textareaId}-hint`} className="text-[12px] text-rt-shadow">
          {hint}
        </p>
      ) : null}
    </div>
  )
}

type RetroSelectProps = SelectHTMLAttributes<HTMLSelectElement> & {
  label?: string
}

export function RetroSelect({ label, className, id, children, ...props }: RetroSelectProps) {
  const autoId = useId()
  const selectId = id ?? autoId
  return (
    <div className="flex flex-col gap-1">
      {label ? (
        <label htmlFor={selectId} className="font-medium">
          {label}
        </label>
      ) : null}
      <div className="relative">
        <select
          id={selectId}
          className={cn(
            'rt-sunken h-7 w-full cursor-pointer appearance-none pr-8 pl-2 text-[13px] text-rt-ink',
            'disabled:cursor-not-allowed disabled:bg-rt-face disabled:text-rt-shadow',
            focusRing,
            className,
          )}
          {...props}
        >
          {children}
        </select>
        <span
          aria-hidden="true"
          className="rt-raised pointer-events-none absolute top-0.5 right-0.5 bottom-0.5 flex w-5.5 items-center justify-center"
        >
          <svg viewBox="0 0 8 8" className="size-2 fill-current">
            <path d="M0 2h8L4 7z" />
          </svg>
        </span>
      </div>
    </div>
  )
}

type ToggleProps = Omit<InputHTMLAttributes<HTMLInputElement>, 'type'> & {
  label: ReactNode
}

const toggleLabel =
  'flex cursor-pointer items-center gap-2 py-0.5 has-disabled:cursor-not-allowed has-disabled:text-rt-shadow'

export function RetroCheckbox({ label, className, ...props }: ToggleProps) {
  return (
    <label className={cn(toggleLabel, className)}>
      <input type="checkbox" className="peer sr-only" {...props} />
      <span
        aria-hidden="true"
        className="rt-sunken flex size-4 shrink-0 items-center justify-center peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-rt-accent peer-checked:[&_svg]:scale-100"
      >
        <svg
          viewBox="0 0 10 10"
          className="size-2.5 scale-0 fill-none stroke-rt-ink stroke-[1.8] transition-transform duration-100"
        >
          <path d="M1.5 5.2 4 7.7 8.5 2.5" strokeLinecap="square" />
        </svg>
      </span>
      <span>{label}</span>
    </label>
  )
}

export function RetroRadio({ label, className, ...props }: ToggleProps) {
  return (
    <label className={cn(toggleLabel, className)}>
      <input type="radio" className="peer sr-only" {...props} />
      <span
        aria-hidden="true"
        className="rt-sunken flex size-4 shrink-0 items-center justify-center rounded-full peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-rt-accent peer-checked:[&_i]:scale-100"
      >
        <i className="block size-1.75 scale-0 rounded-full bg-rt-ink transition-transform duration-100" />
      </span>
      <span>{label}</span>
    </label>
  )
}

export function RetroGroup({
  legend,
  children,
  className,
}: {
  legend: string
  children: ReactNode
  className?: string
}) {
  return (
    <fieldset
      className={cn(
        'rounded-[3px] border border-rt-shadow px-3 pt-1 pb-2.5 shadow-[1px_1px_0_var(--color-rt-light),inset_1px_1px_0_var(--color-rt-light)]',
        className,
      )}
    >
      <legend className="px-1.5 text-[12px] font-semibold tracking-wide">{legend}</legend>
      {children}
    </fieldset>
  )
}

import type { LabelHTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

type RetroLabelProps = LabelHTMLAttributes<HTMLLabelElement> & {
  required?: boolean
}

export function RetroLabel({ required, className, children, ...props }: RetroLabelProps) {
  return (
    <label className={cn('inline-flex items-baseline gap-1 text-[13px] font-medium text-rt-ink', className)} {...props}>
      {children}
      {required ? (
        <span aria-hidden="true" className="text-rt-danger">
          *
        </span>
      ) : null}
    </label>
  )
}

type RetroSeparatorProps = {
  orientation?: 'horizontal' | 'vertical'
  decorative?: boolean
  className?: string
}

export function RetroSeparator({ orientation = 'horizontal', decorative = false, className }: RetroSeparatorProps) {
  return (
    <div
      role={decorative ? 'none' : 'separator'}
      aria-orientation={decorative || orientation === 'horizontal' ? undefined : 'vertical'}
      className={cn(
        orientation === 'horizontal'
          ? 'h-0.5 w-full bg-[linear-gradient(to_bottom,var(--color-rt-shadow)_0_1px,var(--color-rt-light)_1px_2px)]'
          : 'h-full min-h-4 w-0.5 bg-[linear-gradient(to_right,var(--color-rt-shadow)_0_1px,var(--color-rt-light)_1px_2px)]',
        className,
      )}
    />
  )
}

'use client'

import { useId, useRef, useState } from 'react'
import type { KeyboardEvent } from 'react'
import { cn } from '@/lib/utils'

export type RetroListboxOption = { value: string; label: string; disabled?: boolean }

type RetroListboxProps = {
  options: RetroListboxOption[]
  label: string
  multiple?: boolean
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (value: string[]) => void
  className?: string
  listClassName?: string
}

export function RetroListbox({
  options,
  label,
  multiple = false,
  value,
  defaultValue = [],
  onValueChange,
  className,
  listClassName,
}: RetroListboxProps) {
  const baseId = useId()
  const labelId = `${baseId}-label`
  const listRef = useRef<HTMLDivElement>(null)
  const [internal, setInternal] = useState(defaultValue)
  const selected = value ?? internal
  const [active, setActive] = useState(() => {
    const index = options.findIndex((option) => selected.includes(option.value) && !option.disabled)
    return index >= 0 ? index : Math.max(0, options.findIndex((option) => !option.disabled))
  })

  const optionId = (index: number) => `${baseId}-option-${index}`

  function commit(next: string[]) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function choose(index: number) {
    const option = options[index]
    if (!option || option.disabled) return
    setActive(index)
    if (multiple) {
      commit(selected.includes(option.value) ? selected.filter((v) => v !== option.value) : [...selected, option.value])
    } else {
      commit([option.value])
    }
  }

  function step(from: number, direction: 1 | -1) {
    let index = from + direction
    while (index >= 0 && index < options.length && options[index].disabled) index += direction
    return index >= 0 && index < options.length ? index : from
  }

  function moveTo(index: number) {
    if (index < 0 || index >= options.length) return
    setActive(index)
    listRef.current?.children[index]?.scrollIntoView({ block: 'nearest' })
    if (!multiple) choose(index)
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    switch (event.key) {
      case 'ArrowDown':
      case 'ArrowUp':
        event.preventDefault()
        moveTo(step(active, event.key === 'ArrowDown' ? 1 : -1))
        break
      case 'Home':
        event.preventDefault()
        moveTo(step(-1, 1))
        break
      case 'End':
        event.preventDefault()
        moveTo(step(options.length, -1))
        break
      case ' ':
      case 'Enter':
        event.preventDefault()
        choose(active)
        break
    }
  }

  return (
    <div className={cn('flex flex-col gap-1', className)}>
      <span id={labelId} className="font-medium">
        {label}
      </span>
      <div
        ref={listRef}
        role="listbox"
        aria-labelledby={labelId}
        aria-multiselectable={multiple || undefined}
        aria-activedescendant={optionId(active)}
        tabIndex={0}
        onKeyDown={onKeyDown}
        className={cn(
          'group rt-sunken rt-scroll h-32 overflow-auto py-0.5 text-[13px] text-rt-ink',
          'focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-rt-accent',
          listClassName,
        )}
      >
        {options.map((option, index) => {
          const isSelected = selected.includes(option.value)
          return (
            <div
              key={option.value}
              id={optionId(index)}
              role="option"
              aria-selected={isSelected}
              aria-disabled={option.disabled || undefined}
              onClick={() => choose(index)}
              className={cn(
                'cursor-pointer px-2 py-0.5 select-none',
                isSelected ? 'bg-rt-accent text-rt-on-accent' : 'hover:bg-rt-face-hi',
                index === active &&
                  'group-focus-visible:outline-1 group-focus-visible:-outline-offset-1 group-focus-visible:outline-dotted group-focus-visible:outline-current',
                option.disabled && 'cursor-not-allowed text-rt-shadow hover:bg-transparent',
              )}
            >
              {option.label}
            </div>
          )
        })}
      </div>
    </div>
  )
}

