      ) : icon === 'drive' ? (
        <>
          <rect x="1.5" y="5.5" width="13" height="6" fill="var(--color-rt-face)" stroke={line} />
          <path d="M3.5 9h4" stroke={line} />
          <circle cx="12" cy="8.5" r="0.9" fill="var(--color-rt-ok)" />
        </>
      ) : open ? (
        <path d="M1.5 13.5v-9h4.5l1.5 1.5h6v2.5h-9z M3 13.5l1.5-5h10l-1.5 5z" fill="var(--color-rt-warn)" stroke={line} strokeLinejoin="round" />
      ) : (
        <path d="M1.5 3.5h5l1.5 1.5h6.5v8.5h-13z" fill="var(--color-rt-warn)" stroke={line} strokeLinejoin="round" />
      )}
    </svg>
  )
}

type RetroTreeViewProps = {
  label: string
  nodes: RetroTreeNode[]
  defaultExpanded?: string[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  className?: string
}

export function RetroTreeView({
  label,
  nodes,
  defaultExpanded = [],
  value,
  defaultValue,
  onValueChange,
  className,
}: RetroTreeViewProps) {
  const [expanded, setExpanded] = useState(() => new Set(defaultExpanded))
  const [innerSelected, setInnerSelected] = useState<string | undefined>(defaultValue)
  const [focusId, setFocusId] = useState<string | undefined>(defaultValue)
  const itemRefs = useRef(new Map<string, HTMLLIElement>())

  const selected = value ?? innerSelected
  const items = flatten(nodes, expanded)
  const tabbableId = items.some((item) => item.node.id === focusId) ? focusId : items[0]?.node.id

  function setOpen(id: string, open: boolean) {
    setExpanded((current) => {
      const next = new Set(current)
      if (open) next.add(id)
      else next.delete(id)
      return next
    })
  }

  function focusItem(id: string | undefined) {
    if (!id) return
    setFocusId(id)
    itemRefs.current.get(id)?.focus()
  }

  function activate(item: FlatItem) {
    setInnerSelected(item.node.id)
    onValueChange?.(item.node.id)
    if (item.node.children?.length) setOpen(item.node.id, !expanded.has(item.node.id))
  }

  function onKeyDown(event: KeyboardEvent<HTMLUListElement>) {
    const index = items.findIndex((item) => item.node.id === tabbableId)
    const current = items[index]
    if (!current) return
    const hasChildren = Boolean(current.node.children?.length)
    const isOpen = expanded.has(current.node.id)

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        focusItem(items[index + 1]?.node.id)
        break
      case 'ArrowUp':
        event.preventDefault()
        focusItem(items[index - 1]?.node.id)
        break
      case 'ArrowRight':
        event.preventDefault()
        if (hasChildren && !isOpen) setOpen(current.node.id, true)
        else if (hasChildren) focusItem(items[index + 1]?.node.id)
        break
      case 'ArrowLeft':
        event.preventDefault()
        if (hasChildren && isOpen) setOpen(current.node.id, false)
        else focusItem(current.parentId ?? undefined)
        break
      case 'Home':
        event.preventDefault()
        focusItem(items[0]?.node.id)
        break
      case 'End':
        event.preventDefault()
        focusItem(items[items.length - 1]?.node.id)
        break
      case 'Enter':
      case ' ':
        event.preventDefault()
        activate(current)
        break
    }
  }

  return (
    <ul
      role="tree"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={cn('rt-sunken overflow-auto bg-rt-paper p-1 text-[13px] text-rt-ink', className)}
    >
      {items.map((item) => {
        const { node } = item
        const hasChildren = Boolean(node.children?.length)
        const isOpen = expanded.has(node.id)
        const isSelected = selected === node.id
        return (
          <li
            key={node.id}
            ref={(element) => {
              if (element) itemRefs.current.set(node.id, element)
              else itemRefs.current.delete(node.id)
            }}
            role="treeitem"
            aria-level={item.level}
            aria-setsize={item.setSize}
            aria-posinset={item.position}
            aria-expanded={hasChildren ? isOpen : undefined}
            aria-selected={isSelected}
            tabIndex={tabbableId === node.id ? 0 : -1}
            onClick={() => {
              focusItem(node.id)
              activate(item)
            }}
            style={{ paddingLeft: (item.level - 1) * 16 + 4 }}
            className={cn(
              'flex cursor-default items-center gap-1.5 py-0.5 pr-2 select-none outline-none',
              'focus-visible:outline-1 focus-visible:-outline-offset-1 focus-visible:outline-dotted focus-visible:outline-current',
              isSelected ? 'bg-rt-accent text-rt-on-accent' : 'hover:bg-rt-face-hi',
            )}
          >
            <NodeIcon icon={node.icon ?? (hasChildren ? 'folder' : 'file')} open={isOpen} />
            <span className="truncate">{node.label}</span>
          </li>
        )
      })}
    </ul>
  )
}

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

type RetroWindowProps = {
  title: string
  children: ReactNode
  menu?: ReactNode
  status?: ReactNode
  onClose?: () => void
  className?: string
  bodyClassName?: string
  titleAs?: 'h2' | 'h3' | 'p'
}

function TitleGlyph({ kind }: { kind: 'min' | 'max' }) {
  return (
    <svg viewBox="0 0 8 8" className="size-2 fill-current" aria-hidden="true">
      {kind === 'min' ? <path d="M0 2h8L4 7z" /> : <path d="M0 6h8L4 1z" />}
    </svg>
  )
}

export function RetroWindow({
  title,
  children,
  menu,
  status,
  onClose,
  className,
  bodyClassName,
  titleAs: Title = 'h2',
}: RetroWindowProps) {
  const boxClass =
    'rt-raised flex size-5.5 shrink-0 items-center justify-center text-rt-ink'

  return (
    <section
      aria-label={title}
      className={cn(
        'flex flex-col rounded-[5px] border border-rt-line bg-rt-face p-0.75 font-rt text-[13px] text-rt-ink',
        'shadow-[inset_1px_1px_0_var(--color-rt-light),0_2px_0_rgb(0_0_0/0.25),0_16px_32px_-12px_rgb(0_0_0/0.55)]',
        className,
      )}
    >
      <header className="flex items-stretch gap-0.75">
        {onClose ? (
          <button
            type="button"
            onClick={onClose}
            aria-label="Close window"
            className={cn(
              boxClass,
              'transition-colors hover:bg-rt-light active:rt-pressed focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rt-accent',
            )}
          >
            <span className="block h-0.75 w-3 rounded-[1px] border border-rt-line bg-rt-paper" />
          </button>
        ) : (
          <span aria-hidden="true" className={boxClass}>
            <span className="block h-0.75 w-3 rounded-[1px] border border-rt-line bg-rt-paper" />
          </span>
        )}
        <Title className="rt-title flex h-5.5 min-w-0 flex-1 items-center truncate rounded-[2px] px-2.5 font-rt-mono text-[11px] font-semibold tracking-widest uppercase">
          {title}
        </Title>
        <span aria-hidden="true" className={boxClass}>
          <TitleGlyph kind="min" />
        </span>
        <span aria-hidden="true" className={boxClass}>
          <TitleGlyph kind="max" />
        </span>
      </header>

      {menu ? <div className="mt-0.75">{menu}</div> : null}

      <div className={cn('mt-0.75 flex-1 border-t border-rt-shadow/60', bodyClassName)}>{children}</div>

      {status ? (
        <footer className="rt-sunken mt-0.75 flex items-center gap-2 px-2 py-0.5 text-[12px]">
          {status}
        </footer>
      ) : null}
    </section>
  )
}
